    @EventHandler( payloadType=UpdateCustomerEvent.class )
    public void handle( UpdateCustomerEvent event) {
    	LOGGER.info("handling UpdateCustomerEvent - " + event );
    	
	    Customer entity = new Customer();
            entity.setCustomerId( event.getCustomerId() );
            entity.setName( event.getName() );
            entity.setCustomerCode( event.getCustomerCode() );
            entity.setAddress( event.getAddress() );
            entity.setEnterprises( event.getEnterprises() );
            entity.setSalesOrders( event.getSalesOrders() );
            entity.setCustomerType( event.getCustomerType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCustomer( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCustomer( entity );        
    }
    
